use canic_core::ids::BuildNetwork;
use canic_host::canister_build::{CanisterArtifactBuilder, CanisterArtifactBuildOutput, CanisterBuildProfile, WorkspaceBuildContext};
use std::{fs, path::PathBuf, time::Instant};

fn record(role: &str, output: &CanisterArtifactBuildOutput) {
    println!("ARTIFACT {role} {} {} {}", output.wasm_path.display(), output.wasm_gz_path.display(), output.did_path.display());
    println!("TRANSFORMS {role} {:?}", output.transforms);
    println!("PROFILE {role} {:?} {:?}", output.candid_sha256, output.protocol_profile_digest);
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mode = std::env::args().nth(1).ok_or("mode required")?;
    let workspace_root = PathBuf::from("/home/adam/projects/canic");
    let icp_root = workspace_root.join(".tmp/canic114-pipeline-evidence");
    fs::create_dir_all(&icp_root)?;
    let context = WorkspaceBuildContext {
        role: "app".into(), profile: CanisterBuildProfile::Release,
        environment: "local".into(), build_network: BuildNetwork::Local,
        config_path: workspace_root.join("apps/test/test-configs/generated-mixed-topology.toml"),
        workspace_root, icp_root, local_replica: None,
        refresh_canonical_infrastructure_did: false,
        release_build_id: Some("1141141141141141141141141141141141141141141141141141141141141141".parse()?),
    };
    let builder = CanisterArtifactBuilder::for_profile(context.profile)?;
    for line in builder.diagnostic_lines() { println!("{line}"); }
    let started = Instant::now();
    match mode.as_str() {
        "serial" => for role in ["fleet_coordinator", "wasm_store"] {
            let output = builder.build_workspace_canister_artifact(&context.with_role(role))?;
            record(role, &output);
        },
        "pipeline" => {
            let result = builder.build_workspace_app_artifacts(&context, &[])?;
            assert!(result.configured.is_empty());
            record("fleet_coordinator", &result.coordinator.output);
            record("wasm_store", &result.store.output);
        },
        "fail-configured" => {
            assert!(builder.build_workspace_app_artifacts(&context, &["missing-role".into()]).is_err());
            println!("EXPECTED_CONFIGURED_FAILURE");
        },
        _ => return Err("unknown mode".into()),
    }
    println!("WALL {mode} {:.3}", started.elapsed().as_secs_f64());
    Ok(())
}

